#ifndef DUMP_BINARY_WEIGHTS
int init_radebwe(RadeBwe *model, const WeightArray *arrays) {
    if (linear_init(&model->bwe_conv, arrays, "bwe_conv_bias", NULL, NULL,"bwe_conv_weights_float", NULL, NULL, NULL, 60, 128)) return 1;
    if (linear_init(&model->bwe_gru1_input, arrays, "bwe_gru1_input_bias", NULL, NULL,"bwe_gru1_input_weights_float", NULL, NULL, NULL, 128, 384)) return 1;
    if (linear_init(&model->bwe_gru1_recurrent, arrays, "bwe_gru1_recurrent_bias", NULL, NULL,"bwe_gru1_recurrent_weights_float", NULL, NULL, NULL, 128, 384)) return 1;
    if (linear_init(&model->bwe_gru2_input, arrays, "bwe_gru2_input_bias", NULL, NULL,"bwe_gru2_input_weights_float", NULL, NULL, NULL, 128, 384)) return 1;
    if (linear_init(&model->bwe_gru2_recurrent, arrays, "bwe_gru2_recurrent_bias", NULL, NULL,"bwe_gru2_recurrent_weights_float", NULL, NULL, NULL, 128, 384)) return 1;
    if (linear_init(&model->bwe_out, arrays, "bwe_out_bias", NULL, NULL,"bwe_out_weights_float", NULL, NULL, NULL, 128, 19)) return 1;
    return 0;
}
#endif /* DUMP_BINARY_WEIGHTS */
